const LAST_PATCH_DATE = "2026.09.02"; 

export const PEARL_LEVELS = [
  { level: 1, name: 'Ultra Micro 울트라 마이크로', size: '1~5µm', desc: '지문 사이로 스며드는 전분 가루 수준의 극미세 입자 크기를 가진 진주빛 조색제입니다.', faceFlop: '진주조개 안쪽을 긁어낸 듯한 뽀얗고 탁한 우윳빛을 띱니다. 정면과 측면 모두 왜곡 없이 은은하고 부드러운 실키 글로우(Silky Glow)를 일정하게 유지합니다.', usage: '최고급 세단의 깊은 화이트 펄 바탕을 깔거나, 입자가 거친 안료의 톤을 부드럽게 눌러줄 때 처방됩니다.', mix: '투명도가 낮고 은폐력이 매우 뛰어나, 베이스의 밀도를 높이기 위해 지시된 조색 데이터 수치를 정확히 계량합니다.', warning: '메탈릭이 뭉치는 얼룩(Mottling) 현상이 거의 발생하지 않아 초급자도 수월하게 도장할 수 있습니다.', codes: [] },
  { level: 2, name: 'Micro 마이크로', size: '5~10µm', desc: '고운 밀가루 수준의 미세 입자로, 도장 표면을 매끄럽고 차분하게 정돈하는 안료입니다.', faceFlop: 'WT 322 (화이트): 맑은 물에 우유를 한 방울 떨어뜨린 듯한 반투명하고 뽀얀 흰빛을 냅니다.\nWT 357 (실버): 고운 알루미늄 호일을 갈아 넣은 듯 차분하고 매끄러운 쥐색(은빛)이 돕니다.', usage: '매끄러운 질감과 차분한 바탕색이 요구되는 부드러운 순정(OEM) 펄 계열 도장에 광범위하게 적용됩니다.', mix: '입자 배열이 안정적이므로 기본 배합 비율에 맞춰 혼합하며, 타 안료와 섞일 때 변수가 적습니다.', warning: '얼룩 발생 위험이 적어 숨김 도장(보카시) 작업 시 신구 도막의 경계면을 자연스럽게 잇기 유리합니다.', codes: ['WT 322', 'WT 357'] },
  { level: 3, name: 'Fine 파인', size: '10~15µm', desc: '고운 슈가 파우더 크기로 미세한 반짝임과 투명한 질감을 동시에 부여하는 펄 조색제입니다.', faceFlop: 'WT 368 (화이트): 맑은 쌀뜨물처럼 깨끗하고 고운 흰색 진주빛이 유리알처럼 피어오릅니다.\nWT 367 (그린): 맑은 에메랄드 바다나 옅은 옥(玉)을 연상시키는 은은한 초록빛을 띱니다.', usage: '아시아계 양산차 특유의 촘촘하고 밝은 화이트 펄 베이스 컬러 도장 시 핵심적으로 처방됩니다.', mix: '은폐력과 투명성을 동시에 고려하여 설계되었으므로, 지정된 배합 비율을 오차 없이 준수해야 합니다.', warning: '수성 베이스코트 도장 시 플래시 오프(건조) 시간을 정석대로 철저히 지켜야 투명한 질감을 극대화할 수 있습니다.', codes: ['WT 367', 'WT 368'] },
  { level: 4, name: 'Fine Medium 파인 미디엄', size: '15~20µm', desc: '고운 맛소금 정도의 입자 크기로 어떤 바탕과도 자연스럽게 융화되는 중미세 안료입니다.', faceFlop: '특정한 색이 도드라지기보다 바탕색에 스며들어, 은은한 진주빛 코팅을 얇게 씌운 듯한 맑은 광택을 냅니다.', usage: '일반적인 순정(OEM) 밝은 컬러 도장 시 범용적으로 사용되며, 다양한 색상과 무난하게 조화됩니다.', mix: '작업성(은폐력)과 시각적 효과(반짝임)의 밸런스가 뛰어나 지시된 데이터를 기준으로 유연한 혼합이 가능합니다.', warning: '하도(바탕색)가 미세하게 불량하더라도 어느 정도 커버가 가능하여 작업자에게 가장 관대하고 안정성이 높습니다.', codes: [] },
  { level: 5, name: 'Standard Medium 스탠다드 미디엄', size: '20~25µm', desc: '일반 백설탕 크기의 표준 규격으로 은폐력과 광택 반사의 균형이 가장 뛰어난 안료입니다.', faceFlop: 'WT 364 (화이트): 우유 빙수나 바닐라 아이스크림처럼 부드럽고 뽀얀 정통 화이트 진주빛을 냅니다.\nWT 365 (라일락): 연보라색 솜사탕이나 벚꽃 잎처럼 신비롭게 감도는 옅은 보라빛을 띱니다.\nWT 366 (골드): 투명한 샴페인이나 맑은 식용유처럼 찰랑거리는 고급스러운 연한 금빛이 돕니다.', usage: '양산차 보수 도장 현장에서 가장 사용 빈도가 높은 핵심 규격으로 대부분의 표준 펄 컬러에 처방됩니다.', mix: '오리엔테이션 에이전트 등 첨가제 비율 변화에 크게 민감하지 않아 표준 배합 데이터를 따를 때 가장 안정적입니다.', warning: '웻(Wet)하게 뿌리든 드라이(Dry)하게 뿌리든 입자가 고르게 누워 얼룩 발생이 적고 일관된 결과물을 보장합니다.', codes: ['WT 364', 'WT 365', 'WT 366'] },
  { level: 6, name: 'Medium Coarse 미디엄 코어스', size: '25~35µm', desc: '굵은 황설탕 크기로 개별 입자의 반짝임이 시야에 뚜렷하게 들어오기 시작하는 조색제입니다.', faceFlop: 'WT 369 (레드): 잘 익은 체리나 붉은 석류알처럼 검붉은 바탕에 선명하게 맺히는 빨간빛을 냅니다.\nWT 370 (블루): 맑은 가을 하늘이나 이온음료(포카리스웨트)처럼 쨍하고 청량한 파란빛을 뿜어냅니다.', usage: '시선을 사로잡는 생동감 넘치는 레드 펄이나 눈부시게 밝고 선명한 블루 펄 컬러 등에 처방됩니다.', mix: '입자가 무거워지기 시작하므로 도료 내 침전을 막고 고르게 분산시키기 위해 지정된 배합 비율과 점도를 정확히 맞춥니다.', warning: '과도하게 젖은(Wet) 상태로 도포 시 입자가 엉켜 측면이 지저분해질 수 있으므로 일정한 겹침(Overlap)과 거리 유지가 필수입니다.', codes: ['WT 369', 'WT 370'] },
  { level: 7, name: 'Coarse & Xirallic 코어스 및 시랄릭', size: '35~42µm', desc: '굵은 꽃소금 크기로 빛의 굴절을 극대화시킨 투명 고휘도 시랄릭(Xirallic) 펄 조색제입니다.', faceFlop: 'WT 378 (레드): 핏빛 루비 보석을 부수어 놓은 듯 묵직하면서도 날카롭게 반짝이는 붉은빛을 띱니다.', usage: '최고급 화이트 펄 및 특수 고채도 컬러 도장 시 극한의 입체 반사광을 구현하기 위해 처방됩니다.', mix: '입자 배향을 제어하는 오리엔테이션 에이전트(첨가제)의 프리미엄 이펙트 데이터 수치를 정확히 계량해야 합니다.', warning: '에어 압력이 낮거나 하도가 불량하면 측면 멍듦 현상이 발생하므로, 세심한 스프레이 컨트롤과 완벽한 바탕색이 요구됩니다.', codes: ['WT 378'] },
  { level: 8, name: 'High Coarse Diamond 하이 코어스 다이아몬드', size: '42~50µm', desc: '굵은 천일염 크기로 강렬한 난반사와 극단적인 명암 대비를 보여주는 다이아몬드급 이펙트 안료입니다.', faceFlop: 'WT 379 (코퍼): 불에 달궈진 구리선이나 짙은 로즈골드처럼 붉은 기가 감도는 묵직한 동(銅)빛을 냅니다.\nWT 380 (그린): 깊은 산속 이끼나 청포도 캔디처럼 짙고 선명하게 튀어 오르는 초록빛을 띱니다.\nWT 381 (블루): 깊은 바닷속 블루 사파이어나 짙은 남색 잉크처럼 차갑고 묵직한 파란빛이 돕니다.\nWT 382 (골드): 18K 순금 목걸이를 잘게 부숴놓은 듯 누런 기운이 강렬하게 도는 진짜 샛노란 금빛을 뿜어냅니다.', usage: '압도적인 화려함을 뽐내는 골드, 코퍼, 그린, 블루 등 고채도 프리미엄 익스테리어 컬러에 사용됩니다.', mix: '굵은 다이아몬드 입자가 균일하게 도막에 안착할 수 있도록 배합 후 충분하고 부드러운 교반을 거쳐야 합니다.', warning: '숨김 도장(보카시) 시 경계면에 입자가 하얗게 쌓이는 현상(Halo Effect)을 막기 위해 정교한 흩뿌리기 기술이 필요합니다.', codes: ['WT 379', 'WT 380', 'WT 381', 'WT 382'] },
  { level: 9, name: 'Glass Flake 글래스 플레크', size: '50~70µm', desc: '굵은 암염이나 미세한 유리 조각 크기로 유리 특유의 투과율을 이용한 스페셜 유리 편상 안료입니다.', faceFlop: 'WT 392 (매직): 비눗방울 표면이나 홀로그램 스티커처럼 보는 각도에 따라 보라/초록/파랑으로 요동치는 카멜레온빛을 냅니다.\nWT 394 (시안): 몰디브의 얕은 바다나 에메랄드빛 민트 캔디처럼 밝고 형광기가 감도는 쨍한 청록빛을 띱니다.\nWT 395 (블루): 푸른 네온사인처럼 눈이 시릴 정도로 쨍하게 쏘는 형광성 짙은 파란빛이 돕니다.', usage: '신비로운 색상 변화나 압도적인 깊이감을 요구하는 매직 이펙트 및 판타지 커스텀 컬러에 적용됩니다.', mix: '베이스의 은폐력이 없으므로 반드시 완벽하게 조색된 하도(바탕색) 위에 지정된 비율로 혼합하여 투명한 층으로 올려야 합니다.', warning: '건조 후 표면이 거칠어지므로, 투명 클리어를 평소보다 두툼하게 올리고 고품질로 마감해야 완벽한 광택을 낼 수 있습니다.', codes: ['WT 392', 'WT 394', 'WT 395'] },
  { level: 10, name: 'Max Fantasy Extreme 맥스 판타지 익스트림', size: '70µm 이상', desc: '얼음 설탕 조각 크기의 초대형 기재를 사용한 커스텀 전용 맥스 익스트림 안료입니다.', faceFlop: 'WT 396 (그린): 녹색 레이저 포인터나 형광펜처럼 시야를 찌르는 극단적인 초록빛을 뿜어냅니다.\nWT 397 (골드): 한낮의 태양을 정면으로 바라보는 듯 눈부시게 터지는 샛노란 황금빛을 띱니다.\nWT 399 (레드): 용광로의 쇳물이나 붉은 레이저처럼 강렬하게 타오르는 극강의 붉은빛을 냅니다.', usage: '시선을 압도해야 하는 모터쇼 출품 차량이나 극한의 화려함을 추구하는 커스텀 익스테리어 전용 특수 도장에 처방됩니다.', mix: '매우 굵은 특수 입자이므로 일반적인 조색 데이터보다는 작업자의 커스텀 의도와 도막 두께에 맞춘 특수 비율 적용이 필요합니다.', warning: '일반 스프레이 건 노즐 막힘에 주의해야 하며, 클리어 도장 후 샌딩(평탄화) 및 재클리어 공정이 동반되어야 얼룩과 거칠음을 방지할 수 있습니다.', codes: ['WT 396', 'WT 397', 'WT 399'] }
];

const render3DView = () => {
  const SPECTRUM_GRADIENT = "linear-gradient(90deg, #ff0000, #ff7f00, #ffff00, #00ff00, #0000ff, #4b0082, #8b00ff)";
  return (
    <div className="w-full h-full relative overflow-hidden rounded-xl shadow-inner border border-slate-300">
      <div className="absolute inset-0 opacity-100" style={{ background: SPECTRUM_GRADIENT }}></div>
    </div>
  );
};

